<?php

namespace Database\Seeders;

use App\Models\BlogCategory;
use App\Models\BlogPost;
use Carbon\Carbon;
use Illuminate\Database\Seeder;

class BlogPostSeeder extends Seeder
{
    public function run(): void
    {
        $categoryIds = BlogCategory::pluck('id', 'slug')->all();

        // First post goes live in the past to be visible immediately
        $startDate = Carbon::now()->subDays(40)->setTime(10, 0, 0);

        $posts = array_merge(
            $this->eventPosts($categoryIds),
        );

        foreach ($posts as $index => $data) {
            $publishedAt = $startDate->copy()->addWeekdays($index * 4);

            BlogPost::updateOrCreate(
                ['slug' => $data['slug']],
                array_merge($data, [
                    'is_published' => true,
                    'published_at' => $publishedAt,
                ])
            );
        }
    }

        private function eventPosts(array $cats): array
    {
        $catId = $cats['event-tips'] ?? null;
        $cover = 'css/img/events-cover.jpg';

        return [
            [
                'title' => 'Защо професионалната фотография е инвестиция за вашето събитие, а не разход',
                'slug' => 'profesionalna-fotografiya-investiciya-za-sabitieto',
                'category_id' => $catId,
                'cover_image' => $cover,
                'excerpt' => 'Много организатори на събития смятат фотографията за "допълнителен разход". Истината е, че професионалните кадри работят за вас дълго след като събитието е приключило - ето как.',
                'meta_description' => 'Защо професионалната събитийна фотография е инвестиция за вашия бранд и бизнес - практичен анализ от Take Two Studio.',
                'body' => '<p>Събитието свърши. Гостите си тръгнаха. Залата се почисти. Какво остава? Ако нямате професионални кадри - остава само споменът. А споменът не се публикува в Instagram, не се слага в годишния отчет и не убеждава следващия клиент да работи с вас. В тази статия обясняваме защо фотографията на събитието не е ред в бюджета, който се "реже", а инвестиция, която се връща многократно.</p><h2>Кадрите работят дълго след събитието</h2><p>Един корпоративен event трае няколко часа. Но снимките от него живеят с месеци и години. Те отиват в социалните мрежи на компанията, в корпоративния блог, в презентации пред борда на директорите, в материалите за следващото издание на събитието. Една добра снимка от конференция може да бъде използвана десетки пъти в различен контекст.</p><p>За частните събития логиката е подобна, но по-лична. Рожденият ден на детето ви, юбилеят на родителите, голямото семейно тържество - всички тези моменти не се повтарят. Телефонните снимки от масата са мили, но не са същото като професионално уловен момент на изненада, смях или прегръдка.</p><h2>Какво губите без професионален фотограф</h2><p>Нека бъдем конкретни. Ето какво пропускате:</p><p>За бизнес събития - нямате визуално съдържание за маркетинг след събитието. Нямате кадри за press release. Нямате материал за social media постове. Следващия път, когато организирате подобно събитие и искате да покажете "как беше миналата година", нямате какво да покажете.</p><p>За частни тържества - разчитате на снимки от телефони на гости, направени от ъгъл, с лош фокус, в тъмна зала. Моментът, в който дядото танцува с внучката, е пропуснат, защото никой не го е гледал в този момент. Тортата е разрязана, но никой не е снимал реакцията на именника.</p><h2>Какво получавате с професионален екип</h2><p>Разликата не е само в качеството на камерата. Разликата е в опита.</p><p>Професионалният събитиен фотограф знае кога ще се случи ключовият момент. Знае къде да стои, за да хване реакцията. Знае как да работи в тъмна зала, без да ослепява гостите със светкавица. Знае как да е невидим, когато трябва, и как да организира група за обща снимка за по-малко от минута.</p><p>В Take Two Studio работим на събития от години. Знаем ритъма на корпоративна конференция, знаем кога идва кулминацията на рожден ден, знаем как се движи енергията на едно парти. Това ни позволява да предвиждаме, а не просто да реагираме.</p><h2>Колко реално струва пропуснатият момент</h2><p>Помислете така: ако организирате фирмено парти за 50 души, харчите хиляди за зала, кетъринг, DJ, декорация. Ако в края на вечерта нямате нито един професионален кадър, всичко това е било "за момента". Инвестицията в фотограф е малка част от общия бюджет, но е единствената, която ви дава нещо осезаемо след края на вечерта.</p><p>За частните клиенти е още по-просто: колко бихте платили след 10 години, за да видите истински красива снимка от 60-ия рожден ден на баща ви? Стойността расте с времето. Разходът е еднократен.</p><blockquote>Събитието е няколко часа. Снимките от него са завинаги. Не е въпрос на лукс, а на приоритет - какво искате да остане, когато вечерта свърши.</blockquote><p>Ако планирате събитие и обмисляте дали да включите професионална фотография, свържете се с нас за разговор. Ще ви кажем честно какъв тип покритие си струва за вашия конкретен случай и какво можем да ви предложим.</p>',
            ],
            [
                'title' => 'Как да подготвите фирменото си събитие за перфектни снимки и видео',
                'slug' => 'podgotovka-firmeno-sabitie-snimki-video',
                'category_id' => $catId,
                'cover_image' => $cover,
                'excerpt' => 'Организирали сте конференция, лансиране или фирмено парти и искате кадрите да са на ниво. Ето какво можете да направите от ваша страна, за да помогнете на фотографския екип.',
                'meta_description' => 'Как да подготвите корпоративно събитие за професионално заснемане - практичен контролен списък от Take Two Studio.',
                'body' => '<p>Наемането на професионален екип за заснемане е половината работа. Другата половина е подготовката от ваша страна. Много организатори смятат, че е достатъчно да кажат "ела в 18:00 и снимай". Резултатът обикновено е среден. Ето какво прави разликата между "средно" и "отлично".</p><h2>Споделете таймлайна предварително</h2><p>Най-важното нещо, което можете да направите за фотографския екип, е да им дадете подробен план на събитието. Не "идваш в 18, свършваш в 23". А конкретно: кога е регистрацията, кога е официалната част, кога са речите, кога е вечерята, кога е изненадата за директора, кога пускат конфети.</p><p>Когато знаем какво се случва и кога, можем да бъдем на правилното място в правилния момент. Без таймлайн гадаем. И гаденето означава пропуснати моменти.</p><h2>Определете отговорно лице за комуникация с нас</h2><p>На всяко събитие трябва да има един човек, който е нашият контакт. Не генералният директор, не DJ-ят, не сервитьорът. Един конкретен човек, който знае програмата и може да ни каже "след 5 минути е тостът на шефа" или "сега ще внесат тортата".</p><p>Без такъв човек ние питаме наоколо, губим време и пропускаме неща. С такъв човек работим като часовник.</p><h2>Проверете осветлението на залата</h2><p>Отидете в залата ден или два преди събитието. Включете осветлението, което ще е по време на вечерта. Ако залата е много тъмна, помислете за допълнителни лампи. Ако има цветни прожектори, знайте, че те правят лицата на хората да изглеждат неестествено.</p><p>Ние работим с професионално осветление и можем да се справим с почти всяка ситуация. Но колкото по-добра е базовата светлина в залата, толкова по-естествени и красиви ще бъдат кадрите. Съобщете ни предварително за условията, за да носим правилната екипировка.</p><h2>Подгответе зоната за брандиране</h2><p>Ако имате банер, фотостена, лого или друг брандиращ елемент, поставете го на място с добро осветление и достатъчно пространство пред него. Много компании правят красива фотостена, но я слагат в тъмен ъгъл зад колона. Резултатът - никой не я ползва или снимките от нея са тъмни.</p><p>Идеалната фотостена е на добре осветено, достъпно място с поне 3 метра свободно пространство пред нея. Ако логото е на тъмен фон, уверете се, че има насочено осветление към него.</p><h2>Списъкът с "задължителни" кадри</h2><p>Преди събитието ни изпратете списък с нещата, които задължително трябва да заснемем. Примери:</p><ul><li>Кадри с ключови говорители на сцената</li><li>Снимка на целия екип заедно</li><li>Кадри с конкретни VIP гости</li><li>Детайли от декорацията и брандирането</li><li>Моментът на награждаването или изненадата</li><li>Продуктът, който лансирате</li></ul><p>Без списък ще снимаме всичко, което видим. Със списък ще снимаме всичко, което видим, плюс ще сме сигурни, че нищо важно за вас не е пропуснато.</p><h2>Дрескод и визуална консистентност</h2><p>Ако имате дрескод за събитието, споделете го с нас. Ако няма, помислете поне за екипа, който ще е на сцената - да бъдат визуално съгласувани. Група хора в еднакъв стил облекло изглежда професионално на кадър. Група хора, в която един е с костюм, а друг с къси панталони, изглежда хаотично.</p><h2>Храна и достъп за екипа</h2><p>Детайл, който много организатори пропускат: фотографският екип работи на крака целия event. Осигурете им храна и вода. Не е нужно да седят на масата с гостите, но място за бързо хапване и зареждане на батерии е важно. Уморен екип прави по-слаби кадри - това е просто физиология.</p><blockquote>Перфектните снимки от събитие не са резултат само от добра техника. Те са резултат от добра подготовка, ясна комуникация и екип, който знае какво да очаква. Дайте ни тези три неща и ще ви дадем кадри, с които ще се гордеете.</blockquote><p>Ако предстои корпоративно събитие и искате да обсъдим как да го подготвим заедно, свържете се с нас. Правим предварителна среща с всеки корпоративен клиент, за да сме наясно с очакванията от двете страни.</p>',
            ],
            [
                'title' => 'Видео реклами за бизнес - какво предлагаме и как работи процесът',
                'slug' => 'video-reklami-za-biznes-proces',
                'category_id' => $catId,
                'cover_image' => $cover,
                'excerpt' => 'Кратките видео реклами за социални мрежи и по-дългите брандирани видеа са мощен инструмент за всеки бизнес. Ето как протича процесът от идея до готов клип в Take Two Studio.',
                'meta_description' => 'Как създаваме видео реклами за бизнес - от кратки reels до дълги брандирани видеа. Процес и подход от Take Two Studio.',
                'body' => '<p>Видеото е езикът, на който говорят социалните мрежи днес. Статичната снимка вече не е достатъчна, за да спре скролването. Затова все повече бизнеси във Варна и региона идват при нас с един и същи въпрос: "Можете ли да ни направите видео за Instagram и Facebook?" Отговорът е да, и в тази статия обясняваме как точно работи процесът.</p><h2>Два типа видео, които правим</h2><h3>Кратки видеа за социални мрежи (reels, stories, TikTok)</h3><p>Това са клипове с продължителност от 15 до 60 секунди. Бързи, динамични, направени да грабнат вниманието в първите 2-3 секунди. Те са перфектни за ресторанти, барове, магазини, фризьорски салони, фитнес студиа - всеки бизнес, който иска да покаже атмосферата си на живо.</p><p>Кратките видеа не означават кратък процес. Зад 30 секунди финално видео стоят часове заснемане, селекция на най-добрите кадри и монтаж с правилната музика и ритъм. Но крайният продукт е нещо, което можете да публикувате веднага и което работи.</p><h3>По-дълги брандирани видеа</h3><p>Това са клипове от 1 до 5 минути, които разказват историята на вашия бизнес, представят нов продукт, показват процеса зад вашата услуга или документират важно събитие. Те са подходящи за началната страница на уебсайта, за YouTube канала, за презентации пред инвеститори или партньори.</p><p>Брандираното видео изисква повече подготовка - сценарий, локации, координация. Но резултатът е професионален филм, който представя бизнеса ви по начин, по който никоя снимка не може.</p><h2>Как протича процесът</h2><h3>Стъпка 1 - Среща и бриф</h3><p>Започваме с разговор. Какъв е вашият бизнес? Каква е целта на видеото? Кой е вашият клиент? Къде ще се публикува? Какъв е бюджетът? Тези въпроси определят целия подход. Няма универсално видео, което работи за всеки - затова слушаме първо.</p><h3>Стъпка 2 - Концепция и сценарий</h3><p>За кратките reels концепцията е по-свободна - често работим с настроение и атмосфера, а не с конкретен текст. За по-дългите видеа правим сценарий с ключови послания, визуални идеи и структура.</p><h3>Стъпка 3 - Заснемане</h3><p>Идваме с пълно оборудване - камери, обективи, стабилизатор (гимбал), допълнително осветление, микрофони за звук. Снимачният ден може да бъде от няколко часа за прости reels до цял ден за по-мащабни продукции.</p><h3>Стъпка 4 - Монтаж и цветова корекция</h3><p>Суровият материал минава през професионален монтаж. Избираме най-добрите кадри, правим цветова корекция за консистентен вид, добавяме музика и при необходимост - текст, лого и графики. За кратките видеа монтажът е бърз и ритмичен. За дългите - по-кинематографичен.</p><h3>Стъпка 5 - Ревизии и финална версия</h3><p>Изпращаме ви първа версия за преглед. Имате възможност за корекции и промени. След одобрение получавате финалния файл в подходящи формати за всяка платформа.</p><h2>Защо бизнесите избират видео</h2><p>Причината е проста: видеото конвертира. Публикация с видео получава значително повече ангажираност от статична снимка в социалните мрежи. Потенциалните клиенти прекарват повече време на страницата ви, когато има видео. А когато хората виждат реални кадри от вашия бизнес - вашия екип, вашите продукти, вашата атмосфера - доверието расте.</p><h2>За кого е подходящо</h2><p>Работили сме с ресторанти, барове, хотели, козметични студиа, автокъщи, магазини за дрехи, строителни фирми и организатори на събития. Видеото е универсален инструмент - въпросът е какъв формат и стил подхожда на вашата аудитория.</p><blockquote>Едно добре направено видео може да работи за вашия бизнес месеци наред. То не е еднократен разход - то е съдържание, което продължава да привлича клиенти дълго след публикуването.</blockquote><p>Ако искате да обсъдим какъв тип видео би работил за вашия бизнес, свържете се с нас. Първата консултация е безплатна и ще ви дадем конкретна идея какво можем да направим заедно.</p>',
            ],
            [
                'title' => 'Заснемане на заведения и нощен живот - как правим атмосферата видима',
                'slug' => 'zasnemane-zavedeniya-noshten-zhivot',
                'category_id' => $catId,
                'cover_image' => $cover,
                'excerpt' => 'Ресторанти, барове, клубове и нощни заведения имат специфична атмосфера, която е трудна за улавяне с телефон. Ето как работим с тъмни локации, цветни светлини и динамична среда.',
                'meta_description' => 'Как заснемаме ресторанти, барове и нощни заведения професионално - подход, техника и резултати от Take Two Studio.',
                'body' => '<p>Заведението може да има перфектен интериор, невероятни коктейли и жива атмосфера. Но ако снимките в Instagram изглеждат тъмни, размазани и с грозен жълт оттенък от лампите - клиентите няма да го разберат. Заснемането на заведения е едно от нещата, които правим редовно, и знаем защо повечето телефонни снимки не успяват да предадат атмосферата.</p><h2>Предизвикателството на тъмните локации</h2><p>Баровете и клубовете са тъмни по дефиниция. Това е част от атмосферата - приглушена светлина, свещи, неонови акценти, LED ленти. Човешкото око се адаптира и вижда красотата. Телефонната камера не се адаптира по същия начин - тя или прави снимката твърде ярка и плоска, или твърде тъмна и шумна.</p><p>Нашият подход е различен. Работим с камери и обективи, които пропускат значително повече светлина от телефонните. Това ни позволява да запазим естествената атмосфера на заведението, без да я "убиваме" с прекалена светлина. Тъмните ъгли остават тъмни, светлите акценти остават ярки, а лицата на хората изглеждат естествени.</p><h2>Цветните светлини - проклятие или благословия</h2><p>Много заведения работят с цветно осветление - червено, синьо, лилаво, зелено. За телефон това е кошмар - лицата стават неестествено оцветени, кожата изглежда болнава. За нас е възможност. В постпродукцията балансираме цветовете така, че атмосферата да се запази, но хората да изглеждат добре. Това е фина работа, която изисква опит и добро око.</p><h2>Какво заснемаме в едно заведение</h2><h3>Атмосферни кадри</h3><p>Общ план на залата, детайли от интериора, бара, осветлението. Тези кадри разказват историята на мястото - какво усещаш, когато влезеш.</p><h3>Храна и напитки</h3><p>Ако заведението има кухня или бар с интересни коктейли, заснемаме ги в тяхната естествена среда - не в студио, а на бара, на масата, в ръцете на бармана. Това е по-автентично и по-подходящо за социалните мрежи.</p><h3>Хората</h3><p>Гостите, персоналът, DJ-ят, барманът. Заведението без хора е просто стая. Хората му дават живот, и ние улавяме точно това - смях, разговори, танци, моменти.</p><h3>Видео за социални мрежи</h3><p>Кратък клип от 15-30 секунди, който показва атмосферата за една вечер, е много по-ефективен от десет статични снимки. Правим динамични reels с бързи преходи, синхронизирани с музиката на заведението.</p><h2>Как работим на нощно събитие</h2><p>Идваме преди да е пълно - обикновено час преди пиковия момент. Започваме с интериорни и детайлни кадри, докато залата е все още чиста и подредена. Когато гостите започнат да пристигат, преминаваме към атмосферни и портретни кадри. В пиковите часове снимаме динамиката - пълната зала, танците, бара в действие.</p><p>Работим дискретно. Никой не иска фотограф, който стои на пистата и блъска хора с камерата. Ние се движим тихо, използваме телеобективи за кадри от разстояние и влизаме близо само когато моментът го изисква.</p><h2>Честота на заснемане</h2><p>Много от нашите клиенти от заведения работят с нас на регулярна основа - два пъти месечно или веднъж на всяко специално събитие. Това им дава постоянен поток от свежо визуално съдържание за социалните мрежи, без да зависят от телефонни снимки на персонала.</p><h2>Какво получавате</h2><p>В зависимост от уговорката, доставяме обработени снимки и кратки видеа в кратък срок след заснемането - обикновено в рамките на няколко работни дни. Файловете са готови за директно публикуване - правилни размери, обработени цветове, консистентен стил.</p><blockquote>Атмосферата на едно заведение е нещо, което се усеща, не се описва. Нашата работа е да я направим видима - в снимка, в клип, в 15 секунди, които карат някого да каже "искам да отида там".</blockquote><p>Ако управлявате заведение и искате визуално съдържание, което наистина показва какво е мястото ви, свържете се с нас. Ще дойдем, ще видим пространството, и ще ви предложим подход, който работи за вашия формат и аудитория.</p>',
            ],
            [
                'title' => 'Рожден ден, юбилей или частно тържество - как да получите кадри, които ще гледате с години',
                'slug' => 'rozhden-den-yubilei-chastno-tarjestvo-kadri',
                'category_id' => $catId,
                'cover_image' => $cover,
                'excerpt' => 'Частните тържества са пълни с емоции, изненади и спонтанни моменти. Проблемът е, че те се случват бързо и никога не се повтарят. Ето как правим така, че нищо важно да не бъде пропуснато.',
                'meta_description' => 'Как да осигурите професионална фотография за рожден ден, юбилей или частно тържество - практични съвети от Take Two Studio.',
                'body' => '<p>Не всяко събитие е корпоративно. Понякога е 50-ият рожден ден на майка ви, който сте подготвяли месеци. Или юбилеят на баба и дядо, на който цялото семейство се събира за пръв път от години. Или парти за сбогуване с колега, който заминава. Тези моменти са лични, емоционални и неповторими. И точно затова заслужават повече от телефонни снимки.</p><h2>Защо частните тържества са специални за фотографа</h2><p>За разлика от корпоративните събития, където има програма, сцена и говорители, частното тържество е непредсказуемо. Изненадата може да дойде във всеки момент. Сълзите - също. Моментът, в който всички пеят "Честит рожден ден" и именникът духа свещите, трае секунди. Ако не си готов - пропускаш го.</p><p>Ние обичаме тази непредсказуемост. Работим в режим на постоянна готовност - камерата е винаги включена, винаги с правилните настройки, винаги насочена към правилното място. Опитът ни от стотици събития ни е научил къде да гледаме - не към сцената, а към лицата на хората, които гледат сцената.</p><h2>Какво ви трябва от нас за частно тържество</h2><p>Зависи от мащаба. За домашно парти за 20 души е достатъчен един фотограф за няколко часа. За голям юбилей в ресторант за 80 гости с програма може да е нужен и видеооператор. За детски рожден ден с аниматори и игри - отново един фотограф, но с различен подход.</p><p>Не предлагаме "един размер за всички". Обсъждаме конкретно вашето събитие и предлагаме покритие, което има смисъл за вас.</p><h2>Как да ни помогнете за по-добри кадри</h2><h3>Кажете ни кои са ключовите моменти</h3><p>Ще има ли изненада? Кога? Ще се произнася ли някой тост? Кога е тортата? Ще има ли специален подарък? Колкото повече знаем, толкова по-добре сме подготвени.</p><h3>Кажете ни кои хора са важни</h3><p>Не познаваме семейството ви. Ако искате задължително снимка на баба с внуците или на двете сестри заедно, кажете ни предварително. Ще го поставим в нашия списък и ще го направим в подходящия момент.</p><h3>Осигурете добра светлина</h3><p>Ако тържеството е вкъщи, отворете завесите. Ако е в ресторант, попитайте дали могат да увеличат осветлението поне по време на тостовете и тортата. Малките промени в светлината правят голяма разлика в крайния резултат.</p><h2>Детските рождени дни - специален случай</h2><p>Децата не позират. Децата тичат, крещят, ядат торта с ръце и се бият с балони. Това е тяхната магия и ние я обичаме. На детски рожден ден не очаквайте постановени портрети с перфектни усмивки. Очаквайте автентични кадри, в които детето ви е щастливо, разрошено и с шоколад по лицето. Това са снимките, които ще ви разплакват след 20 години.</p><p>Работим с деца по същия начин, както на кръщенета - без светкавица, без команди, с търпение и играчки на камерата.</p><h2>Какво получавате</h2><p>Доставяме обработените снимки в кратък срок - обикновено по-бързо от сватбените проекти, защото обемът е по-малък. Всяка снимка е индивидуално обработена - цветова корекция, баланс, лек ретуш при нужда. Получавате файлове, готови за принтиране, за споделяне в социални мрежи, или за семейния албум.</p><p>Ако искате и видео, правим кратък highlight клип от събитието - няколко минути, с музика и монтаж, които улавят настроението на вечерта.</p><blockquote>Частните тържества не са "по-малко важни" от сватбите. Те са по-различни. По-интимни, по-спонтанни, по-непредсказуеми. И точно затова кадрите от тях са толкова ценни - защото улавят моменти, които никога няма да се повторят.</blockquote><p>Ако планирате рожден ден, юбилей или друго частно тържество и искате да обсъдим дали и как можем да помогнем, пишете ни. Няма твърде малко събитие и няма глупав въпрос.</p>',
            ],
        ];
